<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { BarChart3 } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import StatTile from '@/Core/Components/StatTile.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { QuoteStatus } from '../../../Components/types';
interface Report { currency: string; from: string; to: string; quoted_amount: number; open_weighted_amount: number; actual_sales_amount: number; forecast_amount: number; target_amount: number; target_gap_amount: number; target_attainment_bps: number; active_contract_value_amount: number; quote_count: number; accepted_quote_count: number; order_count: number; conversion_bps: number }
interface Breakdown { status: QuoteStatus; count: number; amount: number } interface Trend { period: string; order_count: number; amount: number }
defineOptions({ layout: TenantLayout }); const props = defineProps<{ report: Report; quoteStatusBreakdown: Breakdown[]; orderTrend: Trend[]; filters: { from: string; to: string; currency: string } }>(); const { t } = useI18n(); const format = useFormat(); const from = ref(props.filters.from); const to = ref(props.filters.to); const currency = ref(props.filters.currency); const columns = computed<Column[]>(() => [{ key: 'status', label: t('crm.fields.status') }, { key: 'count', label: t('crm.reports.count'), align: 'right' }, { key: 'amount', label: t('crm.fields.amount'), align: 'right' }]); const trendMax = computed(() => Math.max(1, ...props.orderTrend.map((item) => item.amount))); function apply(): void { router.get(route('crm.sales.reports.index'), { from: from.value, to: to.value, currency: currency.value }, { preserveState: true, replace: true }); }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.reports.title')" :description="t('crm.reports.description')" /><SalesNav current="reports" /><Card class="mb-3"><form class="grid items-end gap-3 sm:grid-cols-4" @submit.prevent="apply"><Input v-model="from" type="date" :label="t('crm.reports.from')" required /><Input v-model="to" type="date" :label="t('crm.reports.to')" required /><Input v-model="currency" :label="t('crm.fields.currency')" maxlength="3" required /><Button type="submit" variant="primary">{{ t('crm.common.search') }}</Button></form></Card><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatTile :label="t('crm.reports.actualSales')" :value="format.money(report.actual_sales_amount, report.currency)" /><StatTile :label="t('crm.reports.forecast')" :value="format.money(report.forecast_amount, report.currency)" /><StatTile :label="t('crm.reports.target')" :value="format.money(report.target_amount, report.currency)" /><StatTile :label="t('crm.reports.conversionRate')" :value="`${format.number(report.conversion_bps / 100)}%`" /></div><div class="mt-3 grid gap-3 lg:grid-cols-2"><Card :title="t('crm.reports.quoteBreakdown')" flush><DataTable :columns="columns" :rows="quoteStatusBreakdown" row-key="status" :caption="t('crm.reports.quoteBreakdown')"><template #cell-status="{ row }"><CrmStatusBadge :status="row.status" /></template><template #cell-count="{ row }"><span class="tabular font-mono">{{ format.number(row.count) }}</span></template><template #cell-amount="{ row }"><span class="tabular font-mono">{{ format.money(row.amount, report.currency) }}</span></template><template #empty><EmptyState :title="t('crm.reports.empty')" compact><template #icon><BarChart3 /></template></EmptyState></template></DataTable></Card><Card :title="t('crm.reports.orderTrend')"><EmptyState v-if="orderTrend.length === 0" :title="t('crm.reports.empty')" compact><template #icon><BarChart3 /></template></EmptyState><ol v-else class="grid gap-3"><li v-for="item in orderTrend" :key="item.period" class="grid grid-cols-[5rem_1fr_auto] items-center gap-3"><span class="font-mono text-xs text-ink-muted">{{ item.period }}</span><span class="h-2 overflow-hidden rounded-chip bg-hover"><span class="block h-full rounded-chip bg-brand" :style="{ width: `${Math.max(3, item.amount / trendMax * 100)}%` }" /></span><span class="tabular font-mono text-sm text-ink">{{ format.money(item.amount, report.currency) }}</span></li></ol></Card></div></template>
